// ===== Which week is being planned =====
// Riyadh is UTC+3 all year, so the local calendar day is derived by shifting UTC
// rather than by relying on the n8n instance timezone, which this workflow does
// not control.
const RIYADH_OFFSET_MS = 3 * 60 * 60 * 1000;
const nowRiyadh = new Date(Date.now() + RIYADH_OFFSET_MS);
const todayUtcMidnight = Date.UTC(nowRiyadh.getUTCFullYear(), nowRiyadh.getUTCMonth(), nowRiyadh.getUTCDate());

// The Saudi work week starts on Sunday. Always plan the NEXT one: planning the
// current week would create rows whose scheduled time is already in the past.
const dow = new Date(todayUtcMidnight).getUTCDay();
const daysUntilSunday = (7 - dow) || 7;
const weekStart = todayUtcMidnight + daysUntilSunday * 86400000;
const planWeek = new Date(weekStart).toISOString().slice(0, 10);

// Fixes the phase of the 19-week rotation. Any Sunday works as the epoch; this
// one is only a reference point, not a start date.
const EPOCH_SUNDAY = Date.UTC(2026, 0, 4);
const weekIndex = Math.round((weekStart - EPOCH_SUNDAY) / (7 * 86400000));

return [{ json: { planWeek: planWeek, weekIndex: weekIndex } }];

// ===== Expand the week into calendar rows =====
// Five services, one per working day, each on a fixed set of platforms, plus one
// weekly digest. Nothing here decides what is true about a service: the copy,
// the price wording and the links all come from the published feed.

const plan = $('Compute Plan Week').first().json;
const raw = $input.first().json;
// Some hosts serve .json as text/plain, and n8n then hands the body over as a
// string under 'data' instead of a parsed object.
const feed = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;

const rotation = feed.rotation || [];
const grid = feed.grid || [];
const services = feed.services || {};
const per = feed.servicesPerWeek || 5;
const offset = feed.utcOffset || '+03:00';

if (!rotation.length || !grid.length) {
  throw new Error('Content feed returned no rotation or grid — refusing to write an empty week.');
}

// Slice this week's services out of the rotation. It wraps, so the cycle repeats
// after 19 weeks rather than running out.
const start = ((plan.weekIndex * per) % rotation.length + rotation.length) % rotation.length;
const codes = [];
for (let i = 0; i < per; i++) codes.push(rotation[(start + i) % rotation.length]);

const pad2 = (n) => (n < 10 ? '0' + n : '' + n);
const dayIso = (dayOffset) => {
  const t = Date.parse(plan.planWeek + 'T00:00:00Z') + dayOffset * 86400000;
  const d = new Date(t);
  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate());
};

const rows = [];

for (const slot of grid) {
  const code = codes[slot.serviceIndex];
  const s = services[code];
  // A code in the rotation with no entry in services would mean the feed was
  // built from a different catalogue. Skip it rather than write a blank row.
  if (!code || !s) continue;

  const caption = (s.copy && s.copy[slot.channel]) || '';
  if (!caption) continue;

  // The WhatsApp link has to name the channel this row publishes on, or every
  // chat it starts is filed under whichever channel the shared link was tagged.
  const wa = (s.whatsappLinks && s.whatsappLinks[slot.channel]) || s.whatsappLink;

  const notes = [];
  if (wa) notes.push('واتساب مباشر: ' + wa);
  if (s.pack) notes.push('حزمة التصاميم: ' + s.pack);
  if (slot.channel === 'tiktok' && s.tiktok) {
    notes.push('نص الفيديو — الخطاف: ' + s.tiktok.hook);
    notes.push('على الشاشة: ' + s.tiktok.onScreen);
    notes.push('الخاتمة: ' + s.tiktok.cta);
  }
  if (slot.channel === 'snapchat' && s.snapchatSwipeUrl) {
    notes.push('رابط السحب للأعلى: ' + s.snapchatSwipeUrl);
  }

  rows.push({ json: {
    slotKey: plan.planWeek + '|' + code + '|' + slot.platform,
    planWeek: plan.planWeek,
    serviceCode: code,
    platform: slot.platform,
    pillar: slot.pillar,
    scheduled: dayIso(slot.dayOffset) + 'T' + slot.time + ':00' + offset,
    postTitle: s.title + ' — ' + slot.platform,
    captionAr: caption,
    hashtags: s.hashtags || '',
    designBrief: s.designBrief || '',
    landingUrl: (s.links && s.links[slot.channel]) || s.landingUrl || '',
    notes: notes.join('\n'),
  }});
}

// One post a week that is not about a single service, so a follower who missed a
// day still sees the range.
const digest = feed.digest;
if (digest) {
  const lines = ['*' + (digest.title || 'ملخص الأسبوع') + '*', ''];
  for (const code of codes) {
    const s = services[code];
    if (!s) continue;
    lines.push('• ' + s.title + (s.priceTag ? ' — ' + s.priceTag : ''));
    lines.push(((s.links && s.links.telegram) || s.landingUrl) + '');
    lines.push('');
  }
  lines.push(digest.url || '');

  rows.push({ json: {
    slotKey: plan.planWeek + '|DIGEST|' + digest.platform,
    planWeek: plan.planWeek,
    serviceCode: codes.join(', '),
    platform: digest.platform,
    pillar: digest.pillar,
    scheduled: dayIso(digest.dayOffset) + 'T' + digest.time + ':00' + offset,
    postTitle: (digest.title || 'ملخص الأسبوع') + ' — ' + plan.planWeek,
    captionAr: lines.join('\n'),
    hashtags: '',
    designBrief: 'بطاقة ملخص: خمسة عناوين خدمات على خلفية كحلي مع شريط ذهبي، بدون أسعار.',
    landingUrl: digest.url || '',
    notes: 'ملخص أسبوعي — ليس عن خدمة واحدة.',
  }});
}

console.log('PLAN', JSON.stringify({ week: plan.planWeek, services: codes, rows: rows.length }));
return rows;
